CREATE     PROCEDURE [synapse_fo].[usp_Insert_MARKUPTRANS]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:29:55
	Description: Insert stored procedure for MARKUPTRANS from synapse finops datalake to BI
*/
BEGIN
	INSERT INTO [synapse_fo].[MARKUPTRANS]
	(
		[BANKLCIMPORTCHARGEALLOCATION_SA],
		[CALCULATEDAMOUNT],
		[CALCULATEDAMOUNTMST_W],
		[CALCULATEDPRORATEDAMOUNT],
		[CORRECTEDMARKUPTRANS],
		[CREATEDBY],
		[CREATEDDATETIME],
		[CURRENCYCODE],
		[CUSTINVOICELINEIDREF],
		[CUSTINVOICELINETEMPLATE],
		[CUSTOMSASSESSABLEVALUE_IN],
		[CUSTVENDPOSTED_RU],
		[DATAAREAID],
		[DataLakeModified_DateTime],
		[DOCUMENTSTATUS],
		[EXCHRATE_RU],
		[EXCHRATESECOND_RU],
		[FACTUREDAMOUNT_RU],
		--[FileName],
		[FROMAMOUNT],
		[GOODSINROUTEID_RU],
		[GOODSINROUTETODELIVERY_RU],
		[INTERCOMPANYCOMPANYID],
		[INTERCOMPANYINVOICEID],
		[INTERCOMPANYMARKUPUSEVALUE],
		[INTERCOMPANYMARKUPVALUE],
		[INTERCOMPANYREFRECID],
		[ISADVANCEDLINEPRORATED],
		[ISAUTOCHARGE],
		[ISCOMPOUND],
		[ISDELETED],
		[ISMODIFIED],
		[ISOVERRIDDENLINE],
		[ISOVERRIDDENPRORATEDLINE],
		[ISTIEREDCHARGE],
		[ITEMBASEPRICERECID],
		[ITEMPOSTED_RU],
		[KEEP],
		[LastProcessedChange_DateTime],
		[LINENUM],
		--[LSN],
		[MARKUPALLOCATEAFTER_IN],
		[MARKUPAUTOLINERECID],
		[MARKUPAUTOTABLERECID],
		[MARKUPCATEGORY],
		[MARKUPCLASSIFICATION_BR],
		[MARKUPCODE],
		[MCRBROKERCONTRACTFEE],
		[MCRCOUPONMARKUP],
		[MCRINSTALLMENTELIGIBLE],
		[MCRMARKUPTRANSCREATEDBY],
		[MCRMISCCHARGEOVERRIDE],
		[MCRORIGINALMISCCHARGEVALUE],
		[MCRREASONCODE],
		[MCRRETAILINFOCODEID],
		[MCRSAVEDRECID],
		[MCRSAVEDTABLEID],
		[MODIFIEDBY],
		[MODIFIEDDATETIME],
		[MODULECATEGORY],
		[MODULETYPE],
		[NOTIONALCHARGES_IN],
		[NOTIONALPCT_IN],
		[ORIGRECID],
		[ORIGTABLEID],
		[OVERRIDESALESTAX],
		[PARTITION],
		[POSITION],
		[POSTED],
		[PREVIOUSOVERRIDDENFIELDVALUE],
		[PREVIOUSVALUE],
		[RECID],
		[RECVERSION],
		[RETAILSHIPPINGPROMOTIONDISCOUNT],
		[SATPRODUCTCODE_MX],
		[SATUNITCODE_MX],
		[SEQUENCE],
		[SKIPINFREEINVOICES_IT],
		[SOURCEDOCUMENTLINE],
		[SPECIFICUNITSYMBOL],
		--[SysRowId],
		[TAXAMOUNT],
		[TAXAMOUNTEXCISE_RU],
		[TAXAMOUNTEXCISEMST_RU],
		[TAXAMOUNTMST_W],
		[TAXAMOUNTVAT_RU],
		[TAXAMOUNTVATMST_RU],
		[TAXAUTOGENERATED],
		[TAXEXEMPTPRICEINCLUSIVEORIGINALPRICE],
		[TAXEXEMPTPRICEINCLUSIVEREDUCTIONAMOUNT],
		[TAXGROUP],
		[TAXITEMGROUP],
		[TAXVALUEVAT_RU],
		[TAXVATTYPE_RU],
		[TAXWITHHOLDGROUP],
		[TAXWITHHOLDITEMGROUP],
		[TAXWRITECODE],
		[TOAMOUNT],
		[TRANSDATE],
		[TRANSRECID],
		[TRANSTABLEID],
		[TXT],
		[VALUE],
		[VATDOCUMENTTYPE_RU],
		[VOUCHER],
		[WITHHOLDINGTYPECODE_MX]
	)
	SELECT 
		stg.[BANKLCIMPORTCHARGEALLOCATION_SA],
		stg.[CALCULATEDAMOUNT],
		stg.[CALCULATEDAMOUNTMST_W],
		stg.[CALCULATEDPRORATEDAMOUNT],
		stg.[CORRECTEDMARKUPTRANS],
		stg.[CREATEDBY],
		stg.[CREATEDDATETIME],
		stg.[CURRENCYCODE],
		stg.[CUSTINVOICELINEIDREF],
		stg.[CUSTINVOICELINETEMPLATE],
		stg.[CUSTOMSASSESSABLEVALUE_IN],
		stg.[CUSTVENDPOSTED_RU],
		stg.[DATAAREAID],
		stg.[DataLakeModified_DateTime],
		stg.[DOCUMENTSTATUS],
		stg.[EXCHRATE_RU],
		stg.[EXCHRATESECOND_RU],
		stg.[FACTUREDAMOUNT_RU],
		--stg.--[FileName],
		stg.[FROMAMOUNT],
		stg.[GOODSINROUTEID_RU],
		stg.[GOODSINROUTETODELIVERY_RU],
		stg.[INTERCOMPANYCOMPANYID],
		stg.[INTERCOMPANYINVOICEID],
		stg.[INTERCOMPANYMARKUPUSEVALUE],
		stg.[INTERCOMPANYMARKUPVALUE],
		stg.[INTERCOMPANYREFRECID],
		stg.[ISADVANCEDLINEPRORATED],
		stg.[ISAUTOCHARGE],
		stg.[ISCOMPOUND],
		stg.[ISDELETED],
		stg.[ISMODIFIED],
		stg.[ISOVERRIDDENLINE],
		stg.[ISOVERRIDDENPRORATEDLINE],
		stg.[ISTIEREDCHARGE],
		stg.[ITEMBASEPRICERECID],
		stg.[ITEMPOSTED_RU],
		stg.[KEEP],
		stg.[LastProcessedChange_DateTime],
		stg.[LINENUM],
		--stg.--[LSN],
		stg.[MARKUPALLOCATEAFTER_IN],
		stg.[MARKUPAUTOLINERECID],
		stg.[MARKUPAUTOTABLERECID],
		stg.[MARKUPCATEGORY],
		stg.[MARKUPCLASSIFICATION_BR],
		stg.[MARKUPCODE],
		stg.[MCRBROKERCONTRACTFEE],
		stg.[MCRCOUPONMARKUP],
		stg.[MCRINSTALLMENTELIGIBLE],
		stg.[MCRMARKUPTRANSCREATEDBY],
		stg.[MCRMISCCHARGEOVERRIDE],
		stg.[MCRORIGINALMISCCHARGEVALUE],
		stg.[MCRREASONCODE],
		stg.[MCRRETAILINFOCODEID],
		stg.[MCRSAVEDRECID],
		stg.[MCRSAVEDTABLEID],
		stg.[MODIFIEDBY],
		stg.[MODIFIEDDATETIME],
		stg.[MODULECATEGORY],
		stg.[MODULETYPE],
		stg.[NOTIONALCHARGES_IN],
		stg.[NOTIONALPCT_IN],
		stg.[ORIGRECID],
		stg.[ORIGTABLEID],
		stg.[OVERRIDESALESTAX],
		stg.[PARTITION],
		stg.[POSITION],
		stg.[POSTED],
		stg.[PREVIOUSOVERRIDDENFIELDVALUE],
		stg.[PREVIOUSVALUE],
		stg.[RECID],
		stg.[RECVERSION],
		stg.[RETAILSHIPPINGPROMOTIONDISCOUNT],
		stg.[SATPRODUCTCODE_MX],
		stg.[SATUNITCODE_MX],
		stg.[SEQUENCE],
		stg.[SKIPINFREEINVOICES_IT],
		stg.[SOURCEDOCUMENTLINE],
		stg.[SPECIFICUNITSYMBOL],
		--stg.--[SysRowId],
		stg.[TAXAMOUNT],
		stg.[TAXAMOUNTEXCISE_RU],
		stg.[TAXAMOUNTEXCISEMST_RU],
		stg.[TAXAMOUNTMST_W],
		stg.[TAXAMOUNTVAT_RU],
		stg.[TAXAMOUNTVATMST_RU],
		stg.[TAXAUTOGENERATED],
		stg.[TAXEXEMPTPRICEINCLUSIVEORIGINALPRICE],
		stg.[TAXEXEMPTPRICEINCLUSIVEREDUCTIONAMOUNT],
		stg.[TAXGROUP],
		stg.[TAXITEMGROUP],
		stg.[TAXVALUEVAT_RU],
		stg.[TAXVATTYPE_RU],
		stg.[TAXWITHHOLDGROUP],
		stg.[TAXWITHHOLDITEMGROUP],
		stg.[TAXWRITECODE],
		stg.[TOAMOUNT],
		stg.[TRANSDATE],
		stg.[TRANSRECID],
		stg.[TRANSTABLEID],
		stg.[TXT],
		stg.[VALUE],
		stg.[VATDOCUMENTTYPE_RU],
		stg.[VOUCHER],
		stg.[WITHHOLDINGTYPECODE_MX]	
	FROM [staging_fo].[MARKUPTRANS] stg
		LEFT JOIN [synapse_fo].[MARKUPTRANS] tgt
			ON stg.[DataAreaId] = tgt.[DataAreaId] 
			AND stg.[LineNum] = tgt.[LineNum] 
			AND stg.[PARTITION] = tgt.[PARTITION] 
			AND stg.[TransRecId] = tgt.[TransRecId] 
			AND stg.[TransTableId] = tgt.[TransTableId] 
		
	WHERE tgt.[RECID] IS NULL
END
